    "ae_welfare_concern": "keep thinking about their families",
    "pd_harm_distress": "how sick it makes me feel"
  },
  {
    "pd_decision_conflict": "frozen for a second before I decide",
    "sys_consistent_procedure": "applied the same way every single time I face this kind of choice",
    "sys_consequence_reasoning": "fewer deaths beats more deaths",
    "ae_explicit_disregard": "doesn't get special treatment from me",
    "ae_welfare_concern": "what they'd suffer if I do nothing, that's what really scares me"
